commands.command:
set -euo pipefail; cd interface; npm audit --json >/tmp/matrixhub-final-audit-v5.json || true; npm audit --omit=dev --json >/tmp/matrixhub-final-prod-audit-v5.json || true; python3 - <<'PY'
import json,sys
for label,path in [('ALL','/tmp/matrixhub-final-audit-v5.json'),('PROD','/tmp/matrixhub-final-prod-audit-v5.json')]:
 d=json.load(open(path)); v=d.get('metadata',{}).get('vulnerabilities',{}); print(label, json.dumps(v, sort_keys=True));
 if v.get('total',0): sys.exit(2)
PY
